/// anchor == head is a caret. head is the moving end. goal_col survives vertical movement.
#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub struct Selection { pub anchor: Offset, pub head: Offset, pub goal_col: Option<u32> }
impl Selection {
    pub fn caret(at: Offset) -> Self;
    pub fn range(&self) -> CharRange; pub fn is_caret(&self) -> bool;
    pub fn min(&self) -> Offset; pub fn max(&self) -> Offset;
}

/// Invariant after every public method: sorted by min(), pairwise non-overlapping, primary < len().
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Selections { ranges: Vec<Selection>, primary: usize }
impl Selections {
    pub fn single(s: Selection) -> Self;
    pub fn new(ranges: Vec<Selection>, primary: usize) -> Self; // normalizes; merges overlaps, primary follows its range
    pub fn primary(&self) -> Selection; pub fn iter(&self) -> impl Iterator<Item = &Selection>; pub fn len(&self) -> usize;
    pub fn push(&mut self, s: Selection); // becomes primary
    pub fn remove_secondary(&mut self); // collapse to primary only
    pub fn map(&mut self, f: impl FnMut(Selection) -> Selection); // then normalize
    /// Positions after `tx` (pre-state offsets): anchor Left-biased, head Right-biased; then normalize.
    pub fn transformed(&self, tx: &Transaction) -> Selections;
}

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum Movement { Left, Right, WordLeft, WordRight, Up, Down, LineStart, LineEnd, SmartHome, DocStart, DocEnd, Lines(i32) }

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
pub enum Extend { No, Yes }

/// Grapheme-cluster steps (unicode-segmentation); tab width for goal columns; Kate word-boundary rules.
pub struct MoveContext { pub tab_width: u8 }

pub fn move_selection(buf: &TextBuffer, s: Selection, m: Movement, extend: Extend, ctx: &MoveContext) -> Selection;
pub fn move_all(buf: &TextBuffer, sel: &mut Selections, m: Movement, extend: Extend, ctx: &MoveContext);

/// Builds one Transaction by asking `f` for an Edit per selection (pre-state offsets). Returns the
/// transaction and the selections as they will be after it (via Selections::transformed), or an error
/// if `f` produced overlapping edits.
pub fn fan_out(buf: &TextBuffer, sel: &Selections, f: impl FnMut(&TextBuffer, Selection) -> Option<Edit>) -> Result<(Transaction, Selections), TransactionError>;

/// The common cases, built on fan_out:
pub fn insert_text(buf: &TextBuffer, sel: &Selections, text: &str) -> Result<(Transaction, Selections), TransactionError>;
pub fn delete_backward(buf: &TextBuffer, sel: &Selections) -> Result<(Transaction, Selections), TransactionError>; // grapheme or selection
pub fn delete_forward(buf: &TextBuffer, sel: &Selections) -> Result<(Transaction, Selections), TransactionError>;
